INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7260764, 1129271, 153814, '<td valign="top">A birds eye view. :P</td>', 'A birds eye view. :P', '2014-09-08 08:34:47.000000', NULL, 1),
(7260839, 1129228, 159723, '<td valign="top">My favourite!</td>', 'My favourite!', '2014-09-08 11:41:42.000000', NULL, 1),
(7260849, 1129272, 13077, '<td valign="top">Interesting concept. I am not a fan of the editing, though - the sepia tone doesn''t do this image any favors. The lady behind the zipper is out of focus, and there appears to be some motion blur on the zipper. The large border of the same color as the sepia tone contributes to the overall drabness of the image as well.<br/> <br/>More light to allow a smaller aperture for more depth of field as well as a faster shutter speed would have helped, and I think color or plain black and white would have looked better.</td>', 'Interesting concept. I am not a fan of the editing, though - the sepia tone doesn''t do this image any favors. The lady behind the zipper is out of focus, and there appears to be some motion blur on the zipper. The large border of the same color as the sepia tone contributes to the overall drabness of the image as well. More light to allow a smaller aperture for more depth of field as well as a faster shutter speed would have helped, and I think color or plain black and white would have looked better.', '2014-09-08 12:06:45.000000', NULL, 1),
(7260851, 1129228, 13077, '<td valign="top">Good find. I like the gritty textures and look of the environment.<br/> <br/>However, even the in-focus area is lacking in sharpness, and there appears to be a lot of noise reduction or JPG artifacts in the dark areas. This being a static subject, supporting the camera with a tripod or even a monopod might have helped; you could have used a much lower ISO, longer shutter speed and even smaller aperture if you so chose. If you started with a clean and sharp image from the camera and processed to get this same look and feel it would be excellent.</td>', 'Good find. I like the gritty textures and look of the environment. However, even the in-focus area is lacking in sharpness, and there appears to be a lot of noise reduction or JPG artifacts in the dark areas. This being a static subject, supporting the camera with a tripod or even a monopod might have helped; you could have used a much lower ISO, longer shutter speed and even smaller aperture if you so chose. If you started with a clean and sharp image from the camera and processed to get this same look and feel it would be excellent.', '2014-09-08 12:10:30.000000', NULL, 1),
(7260852, 1129300, 13077, '<td valign="top">I like the composition and the way the highlights on the zipper gradually fade into bokeh circles.<br/>I can see where the focus is, but for some reason that area is not very sharp. I can''t tell if it''s because of slight motion blur or maybe it was significantly cropped after you shot it?<br/>B&amp;W was a good choice on this one.</td>', 'I like the composition and the way the highlights on the zipper gradually fade into bokeh circles.I can see where the focus is, but for some reason that area is not very sharp. I can''t tell if it''s because of slight motion blur or maybe it was significantly cropped after you shot it?B&W was a good choice on this one.', '2014-09-08 12:15:07.000000', NULL, 1),
(7260853, 1129295, 118154, '<td valign="top">One of my top picks so far.</td>', 'One of my top picks so far.', '2014-09-08 12:16:47.000000', NULL, 1),
(7260854, 1129349, 13077, '<td valign="top">Yikes!<br/>Well composed photo and an interesting subject and cool take on the challenge subject.<br/>I think it could have been slightly improved by increasing the saturation in the yellows and a little more sharpening.</td>', 'Yikes!Well composed photo and an interesting subject and cool take on the challenge subject.I think it could have been slightly improved by increasing the saturation in the yellows and a little more sharpening.', '2014-09-08 12:16:57.000000', NULL, 1),
(7260944, 1129322, 13077, '<td valign="top">I like the duotone treatment on this one.</td>', 'I like the duotone treatment on this one.', '2014-09-08 14:34:53.000000', NULL, 1),
(7260947, 1129218, 13077, '<td valign="top">Nice composition, lighting and tones and you''ve done a pretty good job making the black dress stand out from a black background, but I think another color dress would have worked better.</td>', 'Nice composition, lighting and tones and you''ve done a pretty good job making the black dress stand out from a black background, but I think another color dress would have worked better.', '2014-09-08 14:35:57.000000', NULL, 1),
(7260951, 1129206, 13077, '<td valign="top">This is very cool. I like the neon colors and the striking contrast, and the composition is great. Maybe it''s a calibration issue but all I see of the fourth row is the bright part of the zipper pull. If it was meant to be that dark, I would have left that out to keep it simple.</td>', 'This is very cool. I like the neon colors and the striking contrast, and the composition is great. Maybe it''s a calibration issue but all I see of the fourth row is the bright part of the zipper pull. If it was meant to be that dark, I would have left that out to keep it simple.', '2014-09-08 14:37:52.000000', NULL, 1),
(7260968, 1129275, 13077, '<td valign="top">This has the makings of a good photo, but it''s lacking in sharpness and the black hair would stand out better with a lot more light.</td>', 'This has the makings of a good photo, but it''s lacking in sharpness and the black hair would stand out better with a lot more light.', '2014-09-08 14:45:11.000000', NULL, 1),
(7260972, 1129338, 13077, '<td valign="top">Good composition, but it could benefit from more sharpness and depth of field to include the YKK letters, and also more contrast.</td>', 'Good composition, but it could benefit from more sharpness and depth of field to include the YKK letters, and also more contrast.', '2014-09-08 14:46:11.000000', NULL, 1),
(7260975, 1129319, 13077, '<td valign="top">Good lighting and composition, and I like the layered textures and patterns. Good placement of the focus and DOF as well.</td>', 'Good lighting and composition, and I like the layered textures and patterns. Good placement of the focus and DOF as well.', '2014-09-08 14:46:53.000000', NULL, 1),
(7260976, 1129271, 13077, '<td valign="top">Visually this is very good, and I think it would make a good print in a sort of abstract way as a study of shapes and textures and colors. I don''t get the concept if there was meant to be one, though.</td>', 'Visually this is very good, and I think it would make a good print in a sort of abstract way as a study of shapes and textures and colors. I don''t get the concept if there was meant to be one, though.', '2014-09-08 14:48:02.000000', NULL, 1),
(7260992, 1129329, 13077, '<td valign="top">Nice simple concept, could have been improved by some technical improvements though. There is some ghosting on the fingers, usually caused by using the flash combined with a slow enough shutter speed to take in ambient light while the subject moves. <br/>It would look better if you used off-camera lighting - doesn''t have to be a flash, just get close to whatever light source it is. That would allow you to use a smaller aperture for more DOF - there''s no reason not to have the entire face in focus for a close-up concept shot like this. <br/>I would also recommend touching up the zipper pull''s chipped paint - easy enough with either a paint brush tool, a mask or selection to do localized brightness/contrast, or even clone stamp.</td>', 'Nice simple concept, could have been improved by some technical improvements though. There is some ghosting on the fingers, usually caused by using the flash combined with a slow enough shutter speed to take in ambient light while the subject moves. It would look better if you used off-camera lighting - doesn''t have to be a flash, just get close to whatever light source it is. That would allow you to use a smaller aperture for more DOF - there''s no reason not to have the entire face in focus for a close-up concept shot like this. I would also recommend touching up the zipper pull''s chipped paint - easy enough with either a paint brush tool, a mask or selection to do localized brightness/contrast, or even clone stamp.', '2014-09-08 14:53:40.000000', NULL, 1),
(7260994, 1129219, 13077, '<td valign="top">Very nice concept and well executed. Simple, and the in-focus areas are well placed. Tilt-shift lens?</td>', 'Very nice concept and well executed. Simple, and the in-focus areas are well placed. Tilt-shift lens?', '2014-09-08 14:54:46.000000', NULL, 1),
(7260997, 1129220, 13077, '<td valign="top">Good concept and mostly well executed. I see a blob in the backdrop on the top left, and leaving off the top of the banana may or may not have been a good choice, if it was misshapen or ugly I probably would have recommended shearing it off and at least composing to include what''s left.</td>', 'Good concept and mostly well executed. I see a blob in the backdrop on the top left, and leaving off the top of the banana may or may not have been a good choice, if it was misshapen or ugly I probably would have recommended shearing it off and at least composing to include what''s left.', '2014-09-08 14:57:00.000000', NULL, 1),
(7261000, 1129302, 13077, '<td valign="top">Interesting. It does have a landscape feel with the patterns of the clothing. Good choice to use B&amp;W, and good focus and tones.</td>', 'Interesting. It does have a landscape feel with the patterns of the clothing. Good choice to use B&W, and good focus and tones.', '2014-09-08 14:57:59.000000', NULL, 1),
(7261004, 1129331, 13077, '<td valign="top">Nice composition. I find the wrinkles in the left portion distracting - maybe tacking it to a piece of cardboard on the non-visible side would have helped, also the bottom left is not quite inside the depth of field.</td>', 'Nice composition. I find the wrinkles in the left portion distracting - maybe tacking it to a piece of cardboard on the non-visible side would have helped, also the bottom left is not quite inside the depth of field.', '2014-09-08 14:59:20.000000', NULL, 1),
(7261008, 1129215, 13077, '<td valign="top">This strikes me as being just a portrayal of existing artwork.</td>', 'This strikes me as being just a portrayal of existing artwork.', '2014-09-08 15:00:29.000000', NULL, 1),
(7261014, 1129345, 13077, '<td valign="top">Good concept, but the moon being out of focus makes it not work so well. I understand getting the DOF high enough in a single shot is very hard with anything but a very wide lens, which makes the moon even smaller, but this method might have worked (disclaimer: I''m not an expert on the rules or past DQ''s, and I haven''t tried it) -<br/>Camera on tripod, pointed at moon, exposure time to several seconds. Large piece of black posterboard behind your zipper to block the moon from the camera. Off-camera light pointed at the zipper, not the cardboard, and lens focus set to distance of the zipper. Fire the flash or flip the light on and off right after the exposure, then move both out of the way, then quickly set the lens focus to infinity.<br/>Come to think of it, I want to try that now...</td>', 'Good concept, but the moon being out of focus makes it not work so well. I understand getting the DOF high enough in a single shot is very hard with anything but a very wide lens, which makes the moon even smaller, but this method might have worked (disclaimer: I''m not an expert on the rules or past DQ''s, and I haven''t tried it) -Camera on tripod, pointed at moon, exposure time to several seconds. Large piece of black posterboard behind your zipper to block the moon from the camera. Off-camera light pointed at the zipper, not the cardboard, and lens focus set to distance of the zipper. Fire the flash or flip the light on and off right after the exposure, then move both out of the way, then quickly set the lens focus to infinity.Come to think of it, I want to try that now...', '2014-09-08 15:05:55.000000', NULL, 1),
(7261016, 1129187, 13077, '<td valign="top">Nice concept and execution, simple but works.</td>', 'Nice concept and execution, simple but works.', '2014-09-08 15:09:08.000000', NULL, 1),
(7261019, 1129193, 13077, '<td valign="top">I like the concept and the lighting &amp; composition. The flower seems a little bit soft, and it also seems a bit too saturation on the green channel. Dropping the green and raising the red would have given it a nice medium yellow tone.</td>', 'I like the concept and the lighting & composition. The flower seems a little bit soft, and it also seems a bit too saturation on the green channel. Dropping the green and raising the red would have given it a nice medium yellow tone.', '2014-09-08 15:13:10.000000', NULL, 1),
(7261020, 1129226, 28742, '<td valign="top"><strike>DNMC!</strike> <br/>...oh wait, nevermind - there is a zipper. Took me awhile to notice it.</td>', 'DNMC! ...oh wait, nevermind - there is a zipper. Took me awhile to notice it.', '2014-09-08 15:13:22.000000', NULL, 1),
(7261021, 1129349, 28742, '<td valign="top">Pushing the envelope! :)</td>', 'Pushing the envelope! :)', '2014-09-08 15:14:08.000000', NULL, 1),
(7261024, 1129227, 28742, '<td valign="top"><img alt="'' . substr(''//www.dpchallenged.com/cms/image/DNMC-police.png'', strrpos(''//www.dpchallenged.com/cms/image/DNMC-police.png'', ''/'') + 1) . ''" border="0" src="//www.dpchallenged.com/cms/image/DNMC-police.png"/> (Very cool image, though!)</td>', ' (Very cool image, though!)', '2014-09-08 15:17:09.000000', NULL, 1),
(7261025, 1128952, 13077, '<td valign="top">I think this could have been improved by having some kind of horizontal grainy texture where the blank space it. Also, this looks a lot smaller than 800px high, was that intentional?</td>', 'I think this could have been improved by having some kind of horizontal grainy texture where the blank space it. Also, this looks a lot smaller than 800px high, was that intentional?', '2014-09-08 15:17:42.000000', NULL, 1),
(7261028, 1129356, 28742, '<td valign="top"><img alt="'' . substr(''//www.dpchallenged.com/cms/image/DNMC-police.png'', strrpos(''//www.dpchallenged.com/cms/image/DNMC-police.png'', ''/'') + 1) . ''" border="0" src="//www.dpchallenged.com/cms/image/DNMC-police.png"/> No penalty though because this is a beautiful, unique and interesting image. :)</td>', ' No penalty though because this is a beautiful, unique and interesting image. :)', '2014-09-08 15:21:32.000000', NULL, 1),
(7261029, 1129219, 28742, '<td valign="top"><img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=118154" rel="nofollow" target="_blank">Tiny</a>, is that you? :P</td>', ' Tiny, is that you? :P', '2014-09-08 15:22:20.000000', NULL, 1),
(7261032, 1129232, 13077, '<td valign="top">I would have liked to see the zipper play a more prominent role in the photo, given the challenge subject. I do like the tones, though, but a different composition and more emphasis on the zipper would have helped.</td>', 'I would have liked to see the zipper play a more prominent role in the photo, given the challenge subject. I do like the tones, though, but a different composition and more emphasis on the zipper would have helped.', '2014-09-08 15:24:16.000000', NULL, 1),
(7261034, 1129295, 28742, '<td valign="top">I wish I had a set of gears like that. ;-)</td>', 'I wish I had a set of gears like that. ;-)', '2014-09-08 15:25:15.000000', NULL, 1),
(7261035, 1129294, 13077, '<td valign="top">Cool concept, and interesting textures on the animal cutouts. The blotches on the red fabric are distracting - a simple HDR processing could have reduced that, or perhaps more flat lighting on the surface.</td>', 'Cool concept, and interesting textures on the animal cutouts. The blotches on the red fabric are distracting - a simple HDR processing could have reduced that, or perhaps more flat lighting on the surface.', '2014-09-08 15:25:32.000000', NULL, 1),
(7261037, 1129109, 28742, '<td valign="top"><img alt="'' . substr(''//www.dpchallenged.com/cms/image/DNMC-police.png'', strrpos(''//www.dpchallenged.com/cms/image/DNMC-police.png'', ''/'') + 1) . ''" border="0" src="//www.dpchallenged.com/cms/image/DNMC-police.png"/></td>', '', '2014-09-08 15:26:23.000000', NULL, 1),
(7261039, 1129227, 13077, '<td valign="top">A very interesting scene and nice environment feel, but I don''t get the zipper theme at all.</td>', 'A very interesting scene and nice environment feel, but I don''t get the zipper theme at all.', '2014-09-08 15:27:41.000000', NULL, 1),
(7261040, 1129226, 13077, '<td valign="top">Good concept, well executed.</td>', 'Good concept, well executed.', '2014-09-08 15:28:10.000000', NULL, 1),
(7261042, 1129290, 13077, '<td valign="top">I like the simplicity, but it''s lacking in sharpness overall.</td>', 'I like the simplicity, but it''s lacking in sharpness overall.', '2014-09-08 15:28:48.000000', NULL, 1),
(7261043, 1129344, 13077, '<td valign="top">Very cool. Good concept and well set up.</td>', 'Very cool. Good concept and well set up.', '2014-09-08 15:29:26.000000', NULL, 1),
(7261045, 1129109, 13077, '<td valign="top">It does kind of look like a zipper, but it looks like either your lens wasn''t set to infinity or you had some camera shake. If you''re not already, try to use the 2-second self timer or a cable/wireless release for shots like this, and if your lens doesn''t have a visible guide for focal point, every time you move or recompose shoot some test photos at the highest ISO and leave it on manual focus.</td>', 'It does kind of look like a zipper, but it looks like either your lens wasn''t set to infinity or you had some camera shake. If you''re not already, try to use the 2-second self timer or a cable/wireless release for shots like this, and if your lens doesn''t have a visible guide for focal point, every time you move or recompose shoot some test photos at the highest ISO and leave it on manual focus.', '2014-09-08 15:31:55.000000', NULL, 1),
(7261053, 1129313, 13077, '<td valign="top">I like the tones and textures in this one, and the depth of field is just right.</td>', 'I like the tones and textures in this one, and the depth of field is just right.', '2014-09-08 15:52:59.000000', NULL, 1),
(7261054, 1129323, 13077, '<td valign="top">Good concept, and great focus and lighting throughout.</td>', 'Good concept, and great focus and lighting throughout.', '2014-09-08 15:53:19.000000', NULL, 1),
(7261055, 1129188, 13077, '<td valign="top">This is an excellent concept, and well executed. Hope it does well.</td>', 'This is an excellent concept, and well executed. Hope it does well.', '2014-09-08 15:53:44.000000', NULL, 1),
(7261057, 1129222, 13077, '<td valign="top">There''s a lot going on in this photo, and it''s all very intriguing. I like it a lot.</td>', 'There''s a lot going on in this photo, and it''s all very intriguing. I like it a lot.', '2014-09-08 15:54:37.000000', NULL, 1),
(7261058, 1129310, 13077, '<td valign="top">I like the simplicity. Looks like the shape of a ribbon, but turned around... I think it would look better if you had not left out the bottom part of the loop, though.</td>', 'I like the simplicity. Looks like the shape of a ribbon, but turned around... I think it would look better if you had not left out the bottom part of the loop, though.', '2014-09-08 15:55:46.000000', NULL, 1),
(7261059, 1129223, 13077, '<td valign="top">Well lit, and sharp with good colors. I would have recommended cropping about half an inch higher to remove that bit at the bottom left corner, and have the photo end right below where the zipper is visible.</td>', 'Well lit, and sharp with good colors. I would have recommended cropping about half an inch higher to remove that bit at the bottom left corner, and have the photo end right below where the zipper is visible.', '2014-09-08 15:56:58.000000', NULL, 1),
(7261060, 1128950, 13077, '<td valign="top">I like the tones and composition, and good job having the reflection in there while maintaining simplicity.</td>', 'I like the tones and composition, and good job having the reflection in there while maintaining simplicity.', '2014-09-08 15:57:44.000000', NULL, 1),
(7261061, 1129277, 13077, '<td valign="top">Very good tones and the way the focus falls off looks great. Rarely does a close-up photo of a face look good without the eyes in focus, but this works well.</td>', 'Very good tones and the way the focus falls off looks great. Rarely does a close-up photo of a face look good without the eyes in focus, but this works well.', '2014-09-08 15:58:38.000000', NULL, 1),
(7261063, 1129335, 13077, '<td valign="top">I don''t know, I like screw-cap milk jugs personally, this looks like it could get messy quick.<br/>Photo-wise - good concept, well set-up but I don''t care for the processing which looks overdone to me. If you didn''t have an original with enough pop, a reshoot with improved light levels would have helped. Unless the editing style was intentional, in which case more power to you, it''s just not my cup of tea.</td>', 'I don''t know, I like screw-cap milk jugs personally, this looks like it could get messy quick.Photo-wise - good concept, well set-up but I don''t care for the processing which looks overdone to me. If you didn''t have an original with enough pop, a reshoot with improved light levels would have helped. Unless the editing style was intentional, in which case more power to you, it''s just not my cup of tea.', '2014-09-08 16:01:22.000000', NULL, 1),
(7261065, 1129018, 13077, '<td valign="top">The lack of light really kept this one from being nice to look at. The grain and lack of focus can work in some cases, but you really want to have at least part of it sharp, and usually for artsy photos where imperfections are the goal you want some dramatic shapes and mystery. This comes across as an accident or a test shot.</td>', 'The lack of light really kept this one from being nice to look at. The grain and lack of focus can work in some cases, but you really want to have at least part of it sharp, and usually for artsy photos where imperfections are the goal you want some dramatic shapes and mystery. This comes across as an accident or a test shot.', '2014-09-08 16:04:21.000000', NULL, 1),
(7261066, 1129199, 13077, '<td valign="top">Pretty sharp overall and well lit, but I''m wondering what this photo is trying to be. If there was a concept, I don''t see it. It could work as a product detail shot with a tighter composition and the concept of demonstrating what the zippers on the bag can do, or maybe selling an active lifestyle with some other outdoor equipment as props.</td>', 'Pretty sharp overall and well lit, but I''m wondering what this photo is trying to be. If there was a concept, I don''t see it. It could work as a product detail shot with a tighter composition and the concept of demonstrating what the zippers on the bag can do, or maybe selling an active lifestyle with some other outdoor equipment as props.', '2014-09-08 16:07:10.000000', NULL, 1),
(7261067, 1129105, 13077, '<td valign="top">Good concept and well executed. Did you have it hanging by the strap with a light to the side casting a shadow on the backdrop and shoot it sideways? Very unique and I like it a lot.</td>', 'Good concept and well executed. Did you have it hanging by the strap with a light to the side casting a shadow on the backdrop and shoot it sideways? Very unique and I like it a lot.', '2014-09-08 16:08:54.000000', NULL, 1),
(7261068, 1129079, 13077, '<td valign="top">This looks like it could be on the product page showing details of the sweater. Well done overall, but the letters look a little soft. I would have recommend a mask or selection to run an additional sharpening filter on just the tag.</td>', 'This looks like it could be on the product page showing details of the sweater. Well done overall, but the letters look a little soft. I would have recommend a mask or selection to run an additional sharpening filter on just the tag.', '2014-09-08 16:10:23.000000', NULL, 1),
(7261069, 1129113, 13077, '<td valign="top">Well lit and sharp, does a good job of showing the details and I like the composition.</td>', 'Well lit and sharp, does a good job of showing the details and I like the composition.', '2014-09-08 16:10:50.000000', NULL, 1),
(7261071, 1129295, 13077, '<td valign="top">Awesome. Nothing I can suggest to improve it, so I''m just left looking forward to seeing what those gears are printed on after the challenge ends. I''m sure it''ll be near the top and easy to find.</td>', 'Awesome. Nothing I can suggest to improve it, so I''m just left looking forward to seeing what those gears are printed on after the challenge ends. I''m sure it''ll be near the top and easy to find.', '2014-09-08 16:12:08.000000', NULL, 1),
(7261072, 1129214, 13077, '<td valign="top">Cute. Good concept and well done, I like the composition and tones a lot.</td>', 'Cute. Good concept and well done, I like the composition and tones a lot.', '2014-09-08 16:12:28.000000', NULL, 1),
(7261074, 1129356, 13077, '<td valign="top">Very cool view of the subject, good focus and perfect DOF. I like the tones, strikes me as a color print film manually enlarged with some actual filters and pushed a stop or so. Well done.</td>', 'Very cool view of the subject, good focus and perfect DOF. I like the tones, strikes me as a color print film manually enlarged with some actual filters and pushed a stop or so. Well done.', '2014-09-08 16:15:18.000000', NULL, 1),
(7261076, 1129333, 13077, '<td valign="top">I bet in the next frame the guy in the zipper starts sliding out and the guy at the bottom steps back and lets him hit the ground. lol</td>', 'I bet in the next frame the guy in the zipper starts sliding out and the guy at the bottom steps back and lets him hit the ground. lol', '2014-09-08 16:15:54.000000', NULL, 1),
(7261085, 1129344, 70265, '<td valign="top">this one will ribbon for sure. Very creative take, well executed!</td>', 'this one will ribbon for sure. Very creative take, well executed!', '2014-09-08 16:42:56.000000', NULL, 1),
(7261086, 1129275, 70265, '<td valign="top">focus</td>', 'focus', '2014-09-08 16:43:15.000000', NULL, 1),
(7261087, 1129188, 70265, '<td valign="top">well done, creative</td>', 'well done, creative', '2014-09-08 16:43:32.000000', NULL, 1),
(7261089, 1129333, 70265, '<td valign="top">sweet. Go Woody!</td>', 'sweet. Go Woody!', '2014-09-08 16:44:07.000000', NULL, 1),
(7261090, 1129228, 70265, '<td valign="top">nice find!</td>', 'nice find!', '2014-09-08 16:45:01.000000', NULL, 1),
(7261099, 1129105, 60173, '<td valign="top">I can only guess that it''s hanging by that thing on the right, but I must commend you on your lighting. You''ve done a great job of getting that shadow "beneath" the camera.</td>', 'I can only guess that it''s hanging by that thing on the right, but I must commend you on your lighting. You''ve done a great job of getting that shadow "beneath" the camera.', '2014-09-08 17:14:59.000000', NULL, 1),
(7261100, 1129356, 60173, '<td valign="top">Not a zipper, but I totally accept it as a zipper. Good eye.</td>', 'Not a zipper, but I totally accept it as a zipper. Good eye.', '2014-09-08 17:16:38.000000', NULL, 1),
(7261152, 1129228, 124982, '<td valign="top">My favorite of the challenge...very nice textures and structure.</td>', 'My favorite of the challenge...very nice textures and structure.', '2014-09-08 20:14:12.000000', NULL, 1),
(7261153, 1129277, 124982, '<td valign="top">Top 2 for me. Lovely composition and posing. Very subtle and appealing!</td>', 'Top 2 for me. Lovely composition and posing. Very subtle and appealing!', '2014-09-08 20:14:41.000000', NULL, 1),
