(7262752, 1129188, 58634, '<td valign="top">This looks really awesome!! Great execution and cool idea. Very colorful and  unique.</td>', 'This looks really awesome!! Great execution and cool idea. Very colorful and  unique.', '2014-09-13 17:24:34.000000', NULL, 1),
(7262754, 1129294, 58634, '<td valign="top">What an interesting and artistic take on this. Very surreal and special.</td>', 'What an interesting and artistic take on this. Very surreal and special.', '2014-09-13 17:25:45.000000', NULL, 1),
