(7262770, 1129302, 58634, '<td valign="top">I like your lighting here. Looks like it came from a neaby window.. similar to the way sometimes, in the early morning light shines in just some places.... hope that makes sense..</td>', 'I like your lighting here. Looks like it came from a neaby window.. similar to the way sometimes, in the early morning light shines in just some places.... hope that makes sense..', '2014-09-13 17:32:38.000000', NULL, 1),
(7262771, 1129344, 58634, '<td valign="top">Oii this makes me cringe! Great editing!</td>', 'Oii this makes me cringe! Great editing!', '2014-09-13 17:32:58.000000', NULL, 1),
(7262772, 1129228, 58634, '<td valign="top">This is an interesting find. I can''t help but wonder what it is? Very cool. I hope you share more info on it on  your notes.</td>', 'This is an interesting find. I can''t help but wonder what it is? Very cool. I hope you share more info on it on  your notes.', '2014-09-13 17:33:23.000000', NULL, 1),
(7262773, 1129277, 58634, '<td valign="top">I like the fact that you wanted to use selective focus on the zipper whilst keeping the rest out of focus, but can''t help but feel like the blurring was overdone and could be smoother. The contrast is really nice, though and I enjoy her expression.</td>', 'I like the fact that you wanted to use selective focus on the zipper whilst keeping the rest out of focus, but can''t help but feel like the blurring was overdone and could be smoother. The contrast is really nice, though and I enjoy her expression.', '2014-09-13 17:34:27.000000', NULL, 1),
(7262774, 1129193, 58634, '<td valign="top">I really like how you can see yellow all throughout the image. It really help the composition tie in nicely</td>', 'I really like how you can see yellow all throughout the image. It really help the composition tie in nicely', '2014-09-13 17:36:25.000000', NULL, 1),
(7262775, 1129218, 58634, '<td valign="top">I like how soft this looks.</td>', 'I like how soft this looks.', '2014-09-13 17:36:45.000000', NULL, 1),
(7262776, 1129329, 58634, '<td valign="top">I had a similar idea for this challenge but didn''t do it so obviously I like your concept. However, the image seems too orange and odd. Did you have a longer exposure?</td>', 'I had a similar idea for this challenge but didn''t do it so obviously I like your concept. However, the image seems too orange and odd. Did you have a longer exposure?', '2014-09-13 17:37:46.000000', NULL, 1),
