(7262782, 1129187, 58634, '<td valign="top">I like the reflection.. and of course, the money ;)</td>', 'I like the reflection.. and of course, the money ;)', '2014-09-13 17:41:41.000000', NULL, 1),
(7262783, 1129322, 58634, '<td valign="top">I think this is one of the only zippers in this challenge that doesn''t say YKK on it. I like the fact that there''s 2 of them there.</td>', 'I think this is one of the only zippers in this challenge that doesn''t say YKK on it. I like the fact that there''s 2 of them there.', '2014-09-13 17:42:16.000000', NULL, 1),
